auto func (auto value){  
    using T = decltype(value);  
    T product = 1;  
    for_each(begin(value), end(value), [&](T x) { product *= x; });  
    return product;  
}

auto func (auto value){  
    auto result = 1;  
    for(auto i = value; i > 0; --i) {  
        result *= i;  
    }  
    return result;  
}
